<?php

declare(strict_types=1);

namespace Toolkit\DocGen\Render;

use function file_get_contents;
use function is_file;
use function sprintf;

use Toolkit\DocGen\DocGenException;
use Toolkit\DocGen\Filesystem\SiteFileWriter;
use Toolkit\DocGen\Render\Social\SocialCard;

/**
 * Publishes the static stylesheet and script assets into the site.
 */
final class AssetPublisher
{
    /** @readonly */
    private SiteFileWriter $writer;

    /** @readonly */
    private SocialCard $card;

    /**
     * Creates an asset publisher.
     */
    public function __construct(?SiteFileWriter $writer = null, ?SocialCard $card = null)
    {
        $this->writer = $writer ?? new SiteFileWriter();
        $this->card = $card ?? new SocialCard();
    }

    /**
     * Publishes all bundled assets and the GitHub Pages marker file.
     *
     * @throws DocGenException when a bundled asset is missing
     */
    public function publish(string $outputRoot): void
    {
        foreach (['document-design-v1.1.0.css', 'document-design-LICENSE.txt', 'style.css', 'app.js'] as $asset) {
            $this->writer->write($outputRoot, 'assets/' . $asset, $this->assetContents($asset));
        }

        $this->writer->write($outputRoot, '.nojekyll', '');
    }

    /**
     * Draws the image a link to the site is previewed with, if it is asked for.
     *
     * A site that does not say where it is published cannot be linked to
     * absolutely, so nothing previews it and nothing is drawn. Neither is
     * anything drawn where the gd extension is missing: the pages then
     * carry no image tag either, and the card is a card without a picture
     * rather than one pointing at a missing file.
     *
     * @param ?string $baseUrl the address the site is published at, if it is known
     * @param string $title the site title, printed as the headline of the card
     * @param string $description what the documented project is, printed below it
     *
     * @throws DocGenException when the image cannot be drawn or written
     */
    public function publishCard(string $outputRoot, ?string $baseUrl, string $title, string $description): void
    {
        if ($baseUrl === null || !$this->card->supported()) {
            return;
        }

        $this->writer->write($outputRoot, SocialCard::PATH, $this->card->render($title, $description));
    }

    /**
     * Reads one bundled asset from the toolkit resources.
     *
     * @throws DocGenException when the asset file is missing or unreadable
     */
    public function assetContents(string $asset): string
    {
        $path = __DIR__ . '/../../../resources/docgen/' . $asset;
        if (!is_file($path)) {
            throw new DocGenException(sprintf('Bundled asset not found: %s', $path));
        }

        $contents = file_get_contents($path);
        if ($contents === false) {
            throw new DocGenException(sprintf('Bundled asset is not readable: %s', $path));
        }

        return $contents;
    }
}
<?php

declare(strict_types=1);

namespace Toolkit\DocGen\Render;

use function sprintf;

use Toolkit\DocGen\Render\Diff\DiffModeControl;
use Toolkit\DocGen\Render\Social\SocialMeta;

/**
 * Renders the shared document shell around every generated page.
 */
final class PageChrome
{
    /**
     * Display mode a diff site starts in before a reader chooses one.
     */
    public const DEFAULT_DIFF_MODE = 'inline';

    /** @readonly */
    private DiffModeControl $diffModes;

    /** @readonly */
    private SocialMeta $social;

    /** @readonly */
    private RepositoryLink $repository;

    /**
     * Creates the page shell renderer from its topbar collaborators.
     */
    public function __construct(?DiffModeControl $diffModes = null, ?SocialMeta $social = null, ?RepositoryLink $repository = null)
    {
        $this->diffModes = $diffModes ?? new DiffModeControl();
        $this->social = $social ?? new SocialMeta();
        $this->repository = $repository ?? new RepositoryLink();
    }

    /**
     * Renders one complete HTML document.
     *
     * @param string $description what this page documents, in one sentence, for the preview a link to it is shown with
     */
    public function page(RenderKit $services, string $pagePath, string $title, string $description, string $breadcrumbHtml, string $sidebarHtml, string $contentHtml): string
    {
        $escaper = $services->escaper;
        $prefix = $services->url->prefix($pagePath);

        return '<!DOCTYPE html>' . "\n"
            . '<html lang="en">' . "\n"
            . '<head>' . "\n"
            . '<meta charset="utf-8">' . "\n"
            . '<meta name="viewport" content="width=device-width, initial-scale=1">' . "\n"
            . sprintf('<title>%s — %s</title>', $escaper->e($title), $escaper->e($services->model->title)) . "\n"
            . $this->social->render($services, $pagePath, $title, $description)
            . sprintf('<link rel="stylesheet" href="%sassets/document-design-v1.1.0.css">', $escaper->e($prefix)) . "\n"
            . sprintf('<link rel="stylesheet" href="%sassets/style.css">', $escaper->e($prefix)) . "\n"
            . $this->bootstrap($services) . "\n"
            . '</head>' . "\n"
            . sprintf('<body data-root="%s">', $escaper->e($prefix)) . "\n"
            . '<a class="skip" href="#content">Skip to content</a><div class="doc">' . "\n"
            . '<aside class="sidebar" id="sidebar" aria-label="Documentation navigation">' . $sidebarHtml . '</aside>' . "\n"
            . '<div class="main">' . "\n"
            . '<header class="topbar">' . "\n"
            . '<button class="btn nav-toggle" id="nav-toggle" type="button" aria-controls="sidebar" aria-expanded="false" title="Toggle navigation">☰</button>' . "\n"
            . '<nav class="breadcrumbs" aria-label="Breadcrumb">' . $breadcrumbHtml . '</nav>' . "\n"
            . '<div class="topbar-tools">' . "\n"
            . '<input class="input input-search" type="search" id="search" aria-label="Search documentation" placeholder="Search… ( / )" autocomplete="off" spellcheck="false">' . "\n"
            . $this->diffModes->render($services)
            . $this->repository->topbar($services)
            . '<button class="btn" type="button" id="theme-toggle" title="Toggle theme">◐</button>' . "\n"
            . '</div>' . "\n"
            . '</header>' . "\n"
            . '<div class="search-results" id="search-results" hidden></div>' . "\n"
            . '<main class="content" id="content">' . "\n" . $this->emptyHint($services) . $contentHtml . '</main>' . "\n"
            . '<footer class="doc-footer">Generated by <a href="https://github.com/k-kinzal/php-ai-toolkit">php-ai-toolkit</a> docgen</footer>' . "\n"
            . '</div></div>' . "\n"
            . sprintf('<script src="%sassets/search-index.js" defer></script>', $escaper->e($prefix)) . "\n"
            . sprintf('<script src="%sassets/app.js" defer></script>', $escaper->e($prefix)) . "\n"
            . '</body>' . "\n"
            . '</html>' . "\n";
    }

    /**
     * Renders the note shown when a page holds none of the changes.
     *
     * The note is hidden until the script finds that showing the changes
     * alone would leave the page empty, which is an answer rather than a
     * blank page: this page is not part of the comparison.
     */
    public function emptyHint(RenderKit $services): string
    {
        if (!$services->diff->isActive()) {
            return '';
        }

        $escaper = $services->escaper;

        return sprintf(
            '<p class="diff-empty" id="diff-empty" data-changes="%s" data-off="%s" hidden></p>',
            $escaper->e(sprintf(
                'Nothing on this page changed between %s and %s.',
                $services->diff->baseLabel(),
                $services->diff->headLabel(),
            )),
            $escaper->e(sprintf(
                'This page documents what %s had and %s no longer has. Switch to Diff to read it.',
                $services->diff->baseLabel(),
                $services->diff->headLabel(),
            )),
        ) . "\n";
    }

    /**
     * Renders the inline script that restores the display preferences.
     *
     * The theme and the diff mode are applied before the document is laid
     * out, so a page never flashes the wrong colors or the whole file when
     * the reader asked for the changes alone.
     */
    public function bootstrap(RenderKit $services): string
    {
        if (!$services->diff->isActive()) {
            return '<script>try{var t=localStorage.getItem("docgen-theme");if(t){document.documentElement.dataset.ddTheme=t}}catch(e){}</script>';
        }

        return '<script>try{var t=localStorage.getItem("docgen-theme");if(t){document.documentElement.dataset.ddTheme=t}'
            . 'document.documentElement.dataset.diffMode=localStorage.getItem("docgen-diff-mode")||"' . self::DEFAULT_DIFF_MODE . '"}catch(e){}</script>';
    }
}
