/* DocGen-specific extensions to the bundled doc-ui v1.1.0 stylesheet.
 * Layout, typography, controls, prose, code, tables and themes come from doc-ui.
 * Keep domain semantics here, using its public --dd-* tokens.
 */

.k-class, .k-method { --dd-tone: var(--dd-blue); --dd-tone-tint: var(--dd-blue-tint); }
.k-interface { --dd-tone: var(--dd-violet); --dd-tone-tint: var(--dd-violet-tint); }
.k-trait { --dd-tone: var(--dd-amber); --dd-tone-tint: var(--dd-amber-tint); }
.k-enum, .k-package { --dd-tone: var(--dd-teal); --dd-tone-tint: var(--dd-teal-tint); }
.k-function { --dd-tone: var(--dd-pink); --dd-tone-tint: var(--dd-pink-tint); }
.k-namespace, .k-constant, .k-document { --dd-tone: var(--dd-slate); --dd-tone-tint: var(--dd-slate-tint); }
.chip-layer { --dd-tone: var(--dd-indigo); --dd-tone-tint: var(--dd-indigo-tint); }
.chip-test { --dd-tone: var(--dd-violet); --dd-tone-tint: var(--dd-violet-tint); }
.chip-doctest, .chip-public, .chip-cov-high { --dd-tone: var(--dd-ok); --dd-tone-tint: var(--dd-ok-tint); }
.chip-visibility, .chip-cov-mid { --dd-tone: var(--dd-warn); --dd-tone-tint: var(--dd-warn-tint); }
.chip-cov-low { --dd-tone: var(--dd-danger); --dd-tone-tint: var(--dd-danger-tint); }

a:is(.k-class, .k-interface, .k-trait, .k-enum, .k-function, .k-namespace) { color: var(--dd-tone); }

/* The topbar can wrap search and comparison controls onto another row. */
html { scroll-padding-top: calc(var(--docgen-topbar-height, var(--dd-topbar-height)) + var(--dd-sp-4)); }
.search-results { top: calc(var(--docgen-topbar-height, var(--dd-topbar-height)) + var(--dd-sp-1)); }
/* Long source paths must share the breadcrumb row with links and separators. */
.breadcrumbs > .breadcrumb-current { flex-shrink: 1; min-width: 0; }

.sidebar-package a { color: var(--dd-teal); font-weight: var(--dd-weight-label); overflow-wrap: anywhere; }
.sidebar-title a { color: inherit; }
.sidebar-list + .sidebar-title { margin-top: var(--dd-sp-3); }

.symbol-head { justify-content: space-between; }
.symbol-meta, .member-meta { display: flex; align-items: center; gap: var(--dd-sp-3); flex-wrap: wrap; }
.symbol-meta { overflow-wrap: anywhere; }
.member-head > pre { flex: 1; min-width: 0; }
.member:target { background: var(--dd-hover); }
.member-meta:focus-within .anchor, .member:hover .anchor { opacity: 1; }
.member-block .table-wrap { margin: 0; }
.private-sig { margin-bottom: var(--dd-sp-2); }
.alias-def { border-top: none; padding-top: var(--dd-sp-1); }
.t-shape-key { color: var(--dd-syn-var); }
.type-note, .section-note, .pkg-count, .ns-counts, .dep-constraint { color: var(--dd-fg-muted); font-size: var(--dd-text-sm); }
.section-note { margin-bottom: var(--dd-sp-4); }
@container dd-content (width <= 40rem) {
  .items thead { display: none; }
}
.pkg-count, .ns-counts { white-space: nowrap; }
.ns-count { margin-right: var(--dd-sp-3); }
.md-target { border-bottom: 1px dotted var(--dd-border); cursor: help; }
.readme { margin-top: var(--dd-sp-6); }
.prose .code-head { max-width: none; }
.example .example-title { margin: 0 auto 0 0; }
.doct { font-style: italic; }
.doct-return { color: var(--dd-ok); }
.doct-output { color: var(--dd-warn); }
.doct-throws { color: var(--dd-danger); }
.usage-list li { display: block; overflow-wrap: anywhere; }
.usage-kind { display: inline-block; min-width: 84px; margin: 0; }
.usage-loc { color: var(--dd-fg-subtle); margin-left: var(--dd-sp-3); }
.test-cases summary { color: var(--dd-ok); }

/* Printed parameter names and types wrap, so release their compact screen widths. */
@media print {
  .param-table :is(td, th):first-child, .param-table :is(td, th):nth-child(2) { width: auto; }
}

/* Source anchors retain physical line numbers and horizontal scrolling. */
pre.source { padding: var(--dd-sp-3) 0; }
.src-line { display: inline; padding: 0 var(--dd-sp-4); }
.src-line:target { background: var(--dd-warn-tint); }
.source-title { font-family: var(--dd-font-mono); overflow-wrap: anywhere; }

/* Edges and node kinds express Composer and deptrac relationships. */
.graph { margin: 0 auto; }
.graph text { font-family: var(--dd-font-mono); font-size: var(--dd-text-sm); }
.node-vendor { stroke: var(--dd-amber); stroke-dasharray: 3 2; }
.node-layer { stroke: var(--dd-indigo); }
.edge-require, .edge-allowed { stroke: var(--dd-link); }
.edge-require-dev { stroke: var(--dd-fg-subtle); stroke-dasharray: 4 3; }
.edge-suggest { stroke: var(--dd-teal); stroke-dasharray: 1.5 3; }
.edge-tip.edge-require, .edge-tip.edge-allowed { stroke: none; fill: var(--dd-link); }
.edge-tip.edge-require-dev { stroke: none; fill: var(--dd-fg-subtle); }
.edge-tip.edge-suggest { stroke: none; fill: var(--dd-teal); }
.graph-legend { justify-content: center; }
.legend-item::before { content: "—"; margin-right: var(--dd-sp-2); font-weight: 700; }
.legend-require::before { color: var(--dd-link); }
.legend-require-dev::before { color: var(--dd-fg-subtle); }
.legend-suggest::before { color: var(--dd-teal); }

/* Comparison display modes and per-argument changes. */

.diff-modes {
  display: inline-flex;
  border: 1px solid var(--dd-border);
  border-radius: var(--dd-radius-sm);
  overflow: hidden;
}

.diff-mode {
  background: none;
  border: none;
  border-left: 1px solid var(--dd-border);
  color: var(--dd-fg-muted);
  font: inherit;
  font-size: var(--dd-text-sm);
  padding: var(--dd-sp-1) var(--dd-sp-3);
  cursor: pointer;
}

.diff-mode:first-child { border-left: none; }

.diff-mode:hover { background: var(--dd-hover); color: var(--dd-fg); }

.diff-mode.is-active { background: var(--dd-link); color: var(--dd-bg); font-weight: 600; }

.diff-empty { color: var(--dd-fg-muted); font-size: var(--dd-text-md); }

.doc-block { margin: 0; }

.sig-plain { display: none; }

/* The state colors, in the two modes that show them. */

:root:not([data-diff-mode="off"]) [data-diff="added"] {
  --docgen-diff-fg: var(--dd-added);
  --docgen-diff-bg: var(--dd-added-tint);
}

:root:not([data-diff-mode="off"]) [data-diff="removed"] {
  --docgen-diff-fg: var(--dd-removed);
  --docgen-diff-bg: var(--dd-removed-tint);
}

:root:not([data-diff-mode="off"]) [data-diff="modified"] {
  --docgen-diff-fg: var(--dd-modified);
  --docgen-diff-bg: transparent;
}

:root:not([data-diff-mode="off"]) .member[data-diff="added"],
:root:not([data-diff-mode="off"]) .member[data-diff="removed"],
:root:not([data-diff-mode="off"]) .member[data-diff="modified"],
:root:not([data-diff-mode="off"]) .doc-block[data-diff="added"],
:root:not([data-diff-mode="off"]) .doc-block[data-diff="removed"],
:root:not([data-diff-mode="off"]) .private-sig[data-diff="added"],
:root:not([data-diff-mode="off"]) .private-sig[data-diff="removed"],
:root:not([data-diff-mode="off"]) .private-sig[data-diff="modified"],
:root:not([data-diff-mode="off"]) pre.signature[data-diff="added"],
:root:not([data-diff-mode="off"]) pre.signature[data-diff="removed"],
:root:not([data-diff-mode="off"]) pre.signature[data-diff="modified"] {
  background: var(--docgen-diff-bg);
  box-shadow: inset 3px 0 0 var(--docgen-diff-fg);
  border-radius: var(--dd-radius-sm);
  padding-left: var(--dd-sp-5);
}

:root:not([data-diff-mode="off"]) .member[data-diff="removed"] .member-sig,
:root:not([data-diff-mode="off"]) .doc-block[data-diff="removed"] { opacity: 0.85; }

:root:not([data-diff-mode="off"]) .diff-banner {
  border-left-color: var(--docgen-diff-fg);
  background: var(--docgen-diff-bg);
  color: var(--dd-fg);
}

:root:not([data-diff-mode="off"]) .sig-param[data-diff="added"],
:root:not([data-diff-mode="off"]) .sig-param[data-diff="removed"],
:root:not([data-diff-mode="off"]) .sig-param[data-diff="modified"] {
  background: var(--docgen-diff-bg);
  box-shadow: 0 0 0 2px var(--docgen-diff-bg);
  border-radius: 2px;
}

:root:not([data-diff-mode="off"]) .sig-param[data-diff="removed"] {
  text-decoration: line-through;
  text-decoration-color: var(--dd-removed);
}

:root:not([data-diff-mode="off"]) .sig-param[data-diff="modified"] { box-shadow: inset 0 -2px 0 var(--dd-modified); }

/* Listing rows and navigation entries are single lines rather than blocks
 * with their own marked parts, so they carry the state as a fill: a scan of
 * a table or of the sidebar shows what the revision touched. */

:root:not([data-diff-mode="off"]) tr[data-diff="added"] > td,
:root:not([data-diff-mode="off"]) tr[data-diff="removed"] > td,
:root:not([data-diff-mode="off"]) .sidebar-list li[data-diff="added"],
:root:not([data-diff-mode="off"]) .sidebar-list li[data-diff="removed"] { background: var(--docgen-diff-bg); }

:root:not([data-diff-mode="off"]) tr[data-diff="modified"] > td,
:root:not([data-diff-mode="off"]) .sidebar-list li[data-diff="modified"] { background: var(--dd-modified-tint); }

:root:not([data-diff-mode="off"]) tr[data-diff="added"] > td:first-child,
:root:not([data-diff-mode="off"]) tr[data-diff="removed"] > td:first-child,
:root:not([data-diff-mode="off"]) tr[data-diff="modified"] > td:first-child,
:root:not([data-diff-mode="off"]) .sidebar-list li[data-diff="added"],
:root:not([data-diff-mode="off"]) .sidebar-list li[data-diff="removed"],
:root:not([data-diff-mode="off"]) .sidebar-list li[data-diff="modified"] { box-shadow: inset 2px 0 0 var(--docgen-diff-fg); }

:root:not([data-diff-mode="off"]) .sidebar-list li[data-diff="removed"] > a { text-decoration: line-through; }

:root:not([data-diff-mode="off"]) .src-line[data-diff="added"],
:root:not([data-diff-mode="off"]) .src-line[data-diff="removed"] { background: var(--docgen-diff-bg); }

:root:not([data-diff-mode="off"]) .src-line[data-diff="added"] .ln,
:root:not([data-diff-mode="off"]) .src-line[data-diff="removed"] .ln { color: var(--docgen-diff-fg); opacity: 1; }

/* Off: the head revision alone, as if nothing were being compared. */

[data-diff-mode="off"] [data-diff="removed"] { display: none; }

[data-diff-mode="off"] .sig-diff { display: none; }

[data-diff-mode="off"] .sig-plain { display: inline; }

/* Changes: what the revision touched, and nothing else. Source lines and
 * signature parameters keep their neighbours, because a line or an argument
 * without the declaration around it cannot be read. */

[data-diff-mode="changes"] [data-diff="same"]:not(.src-line):not(.sig-param) { display: none; }

