  const context = await browser.newContext({ viewport: { width: 1440, height: 1050 }, colorScheme: 'light', offline: true, permissions: ['clipboard-read', 'clipboard-write'] });
  const errors = [], network = [], failures = [], checks = [];
  context.on('page', p => {
    p.on('pageerror', e => errors.push(e.message));
    p.on('request', r => { if (/^https?:/.test(r.url())) network.push(r.url()); });
    p.on('requestfailed', r => failures.push(r.url() + ': ' + r.failure()?.errorText));
  });
  const page = await context.newPage();
  async function load(file) {
    await page.goto(url(file));
