  assert(page.url().endsWith('class.PageChrome.html'));
  assert((await page.locator('link[rel="stylesheet"]').first().getAttribute('href')).startsWith('../../../../../'));
  await page.locator('#theme-toggle').click();
  assert.equal(await page.locator('html').getAttribute('data-dd-theme'), 'dark');
  await page.reload();
  assert.equal(await page.locator('html').getAttribute('data-dd-theme'), 'dark');
  await page.screenshot({ path: path.join(out, 'nested-dark.png') });
  checks.push('file:// root and nested pages, offline search navigation, dark theme and reload');

  await load('build/docui-v1.2.1-qa/site/validation/japanese/Example/class.Greeting.html');
